package tsumiki

import (
	"fmt"
	"strconv"
	"strings"
	"sync"
)

// glyphOutline is a character's outline as generated by internal/fontgen.
type glyphOutline struct {
	advance int    // font units
	path    string // see glyphOutlines
}

// pathCommand is one step of an outline: M, L, Q or C with its points (font units, y up), or Z.
type pathCommand struct {
	op     byte
	points []Vector2
}

var (
	parseGlyphsOnce sync.Once
	parsedGlyphs    map[rune][]pathCommand
)

func glyphCommands(r rune) ([]pathCommand, bool) {
	parseGlyphsOnce.Do(func() {
		parsedGlyphs = make(map[rune][]pathCommand, len(glyphOutlines))
		for r, g := range glyphOutlines {
			parsedGlyphs[r] = parseOutline(g.path)
		}
	})
	commands, ok := parsedGlyphs[r]
	return commands, ok
}

func parseOutline(path string) []pathCommand {
	var commands []pathCommand
	fields := strings.Fields(path)
	for i := 0; i < len(fields); {
		op := fields[i][0]
		i++
		count := map[byte]int{'M': 1, 'L': 1, 'Q': 2, 'C': 3, 'Z': 0}[op]
		command := pathCommand{op: op}
		for range count {
			x, _ := strconv.ParseFloat(fields[i], 64)
			y, _ := strconv.ParseFloat(fields[i+1], 64)
			command.points = append(command.points, Vector2{x, y})
			i += 2
		}
		commands = append(commands, command)
	}
	return commands
}

// textWidth is the advance width of text set at size (the em, in millimeters).
func textWidth(text string, size float64) (float64, error) {
	total := 0
	for _, r := range text {
		g, ok := glyphOutlines[r]
		if !ok {
			return 0, fmt.Errorf("tsumiki: no glyph for %q in drawing text %q", r, text)
		}
		total += g.advance
	}
	return float64(total) * size / 1000, nil
}

// textOutlines turns a text mark into outlines in paper millimeters (y down), placed and turned
// the way the mark says.
func textOutlines(m mark) ([][]pathCommand, error) {
	width, err := textWidth(m.text, m.size)
	if err != nil {
		return nil, err
	}
	start := map[string]float64{anchorStart: 0, anchorMiddle: -width / 2, anchorEnd: -width}[m.anchor]
	at, scale := m.points[0], m.size/1000
	place := func(pen float64, p Vector2) Vector2 {
		along, up := pen+p.X*scale, p.Y*scale // along the baseline, and away from it
		if m.vertical {                       // reading upwards: along is -y, up is -x
			return Vector2{at.X - up, at.Y - along}
		}
		return Vector2{at.X + along, at.Y - up}
	}
	var outlines [][]pathCommand
	pen := start
	for _, r := range m.text {
		commands, _ := glyphCommands(r)
		placed := make([]pathCommand, len(commands))
		for i, command := range commands {
			placed[i] = pathCommand{op: command.op, points: make([]Vector2, len(command.points))}
			for k, point := range command.points {
				placed[i].points[k] = place(pen, point)
			}
		}
		outlines = append(outlines, placed)
		pen += float64(glyphOutlines[r].advance) * scale
	}
	return outlines, nil
}
